    """
    Calcola il numero di divisori di un intero positivo n.
    """
    if n <= 0:
        return 0

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count
