def longest_common_subsequence(s1, s2, len1, len2):
    # Crea una matrice DP di dimensioni (len1+1) x (len2+1)
    dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

    # Riempimento della matrice DP
    for i in range(1, len1 + 1):
        for j in range(1, len2 + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # La lunghezza della LCS è nell'angolo in basso a destra
    return dp[len1][len2]
```

